:root{--primary:#1b8168;--on-primary:#fff;--primary-fg:#117b63;--primary-soft:#dcf5ec;--accent-soft:#eaf2ce;--accent-fg:#56701f;
--cream:#f4f8f0;--line:#e2eadf;--line-strong:#cbdac7;--paper:#fff;--ink:#1e2e27;--ink-soft:#5c7069;--danger:#b23b3b;--danger-soft:#f6e4e2;--mint-soft:#d8f0e6;--lime-soft:#eaf2ce;}
*{box-sizing:border-box}
.phone{max-width:400px;margin:0 auto;background:var(--cream);font-family:Figtree,'Segoe UI',system-ui,sans-serif;color:var(--ink);border:1px solid var(--line);border-radius:28px;overflow:hidden;padding-bottom:8px}
.top{padding:18px 20px 6px;font-family:'Bricolage Grotesque','Segoe UI',sans-serif;font-size:24px;font-weight:800}
.sub{padding:0 20px;color:var(--ink-soft);font-size:14px}
.card{margin:16px 20px 0;background:var(--paper);border:1px solid var(--line);border-radius:24px;padding:16px}
.eyebrow{font-size:12px;font-weight:800;letter-spacing:.12em;color:var(--ink-soft);text-transform:uppercase}
.field{display:flex;flex-direction:column;gap:6px;margin-top:14px}
.field label{font-size:14px;font-weight:700}
.hint{font-size:12.5px;color:var(--ink-soft)}
.input{border:1.5px solid var(--line);background:var(--cream);border-radius:12px;padding:10px 14px;font-size:15px;color:var(--ink)}
.input.invalid{border-color:var(--danger)}
.err{font-size:13px;color:var(--danger);font-weight:700}
.row{display:flex;gap:12px;align-items:center}
.date{display:flex;flex-direction:column;align-items:center;justify-content:center;width:56px;height:64px;border-radius:18px;background:var(--accent-soft)}
.date .d{font-family:'Bricolage Grotesque',sans-serif;font-size:26px;font-weight:800;line-height:1}
.date .w{font-size:11px;font-weight:800;letter-spacing:.1em;color:var(--accent-fg)}
.badges{display:flex;flex-wrap:wrap;gap:8px;margin-top:12px;align-items:center}
.badge{border-radius:999px;padding:4px 10px;font-size:12.5px;font-weight:800}
.b-points{background:var(--lime-soft);color:var(--accent-fg)}
.b-price{background:var(--primary-soft);color:var(--primary-fg)}
.b-paid{background:var(--mint-soft);color:#12604d}
.b-due{background:var(--accent-soft);color:var(--accent-fg)}
.muted{font-size:13px;color:var(--ink-soft)}
.footer{position:relative;margin-top:20px;border-top:1px solid var(--line);background:var(--cream);padding:14px 20px 18px;display:flex;flex-direction:column;gap:10px}
.cta{min-height:56px;width:100%;border-radius:999px;font-size:17px;font-weight:800;border:0;display:flex;align-items:center;justify-content:center;gap:8px;text-decoration:none}
.cta-primary{background:var(--primary);color:var(--on-primary)}
.cta-outline{background:transparent;border:1.5px solid var(--line-strong);color:var(--ink)}
.status{border-radius:16px;padding:10px 12px;font-size:14px;font-weight:700}
.st-paid{background:var(--mint-soft);color:#12604d}
.st-due{background:var(--accent-soft);color:var(--accent-fg)}
.state{font-size:11px;font-weight:800;color:var(--ink-soft);text-transform:uppercase;letter-spacing:.1em;margin:18px 20px -6px}
.att{margin:10px 20px 0;display:flex;gap:12px;align-items:flex-start;background:var(--cream);border:1px solid var(--line);border-radius:16px;padding:15px;background:#fff}
.att input{width:24px;height:24px;accent-color:var(--primary);margin-top:2px}
.att .name{font-size:15.5px;font-weight:700}
.pill{display:inline-block;margin-top:6px;border-radius:999px;padding:2px 10px;font-size:10.5px;font-weight:800}
.p-kids{background:var(--mint-soft);color:#12604d}
.p-out{border:1px solid var(--line);background:var(--cream);color:var(--ink-soft)}
.toggles{display:flex;flex-direction:column;gap:8px;align-items:flex-end;flex:none}
.tg{display:flex;gap:6px;align-items:center;font-size:12.5px;font-weight:700}
.switch{width:40px;height:24px;border-radius:999px;background:var(--line-strong);position:relative}
.switch::after{content:'';position:absolute;top:3px;left:3px;width:18px;height:18px;border-radius:50%;background:#fff}
.switch.on{background:var(--primary)}.switch.on::after{left:19px}
.summary{margin:14px 20px 0;font-size:14px;color:var(--ink-soft)}
.sheet{margin:16px 12px 0;background:var(--paper);border-radius:24px 24px 16px 16px;padding:18px;border:1px solid var(--line)}
.sheet h3{margin:0 0 4px;font-family:'Bricolage Grotesque',sans-serif;font-size:20px}
.tcard{margin:10px 20px 0;background:#fff;border:1px solid var(--line);border-radius:20px;padding:14px}
.tcard .t{font-weight:800}

